import { lazy, Suspense, useState } from 'react';
const ChartPanel = lazy(() => import('./ChartPanel'));   // separate chunk

export function Report() {
  const [show, setShow] = useState(false);
  return (
    <>
      <button onClick={() => setShow(true)}
              onMouseEnter={() => import('./ChartPanel')}>  {/* prefetch on intent */}
        Show chart
      </button>
      {show && (
        <Suspense fallback={<p>Loading chart...</p>}>
          <ChartPanel />
        </Suspense>
      )}
    </>
  );
}

// on demand, inside a handler
async function exportXlsx(rows: Row[]) {
  const { utils, writeFile } = await import('xlsx');
  const wb = utils.book_new();
  utils.book_append_sheet(wb, utils.json_to_sheet(rows), 'Report');
  writeFile(wb, 'report.xlsx');
}

