function ConfirmDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const dialog = ref.current!;
    if (open && !dialog.open) dialog.showModal();   // focus moves in, background inert
    if (!open && dialog.open) dialog.close();       // browser restores focus to opener
  }, [open]);
  return (
    <dialog ref={ref} aria-labelledby="dlg-title" onClose={onClose}>
      <h2 id="dlg-title">Delete project?</h2>
      <button onClick={onClose}>Cancel</button>
      <button onClick={confirmDelete}>Delete</button>
    </dialog>
  );
}

