import { useVirtualizer } from '@tanstack/react-virtual';

function Rows({ rows }: { rows: Row[] }) {
  const parentRef = useRef<HTMLDivElement>(null);
  const v = useVirtualizer({ count: rows.length, getScrollElement: () => parentRef.current, estimateSize: () => 40 });
  return (
    <div ref={parentRef} style={{ height: 600, overflow: 'auto' }}>
      <div style={{ height: v.getTotalSize(), position: 'relative' }}>
        {v.getVirtualItems().map((item) => (
          <div key={rows[item.index].id}
               style={{ position: 'absolute', top: 0, transform: `translateY(${item.start}px)`, height: 40 }}>
            {rows[item.index].name}
          </div>
        ))}
      </div>
    </div>
  );
}

function ProductSearch({ products }: { products: Product[] }) {
  const [query, setQuery] = useState('');
  const deferredQuery = useDeferredValue(query);
  const results = useMemo(
    () => products.filter((p) => p.name.toLowerCase().includes(deferredQuery.toLowerCase())),
    [products, deferredQuery],
  );
  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />   {/* stays instant */}
      <ResultsList items={results} stale={query !== deferredQuery} />
    </>
  );
}

